<?php
declare(strict_types=1);
namespace Giftcheta\Modules\Cart;

use PDO;

final class CartRepository
{
    public function __construct(private readonly PDO $db) {}
    public function cartId(string $keyHash,bool $create=false): ?int
    { $q=$this->db->prepare("SELECT id,(expires_at>NOW()) AS is_current FROM carts WHERE guest_key_hash=? AND status='active' LIMIT 1");$q->execute([$keyHash]);$existing=$q->fetch();if($existing&&((int)$existing['is_current']===1))return (int)$existing['id'];if(!$create)return null;if($existing){$this->db->prepare("UPDATE carts SET guest_key_hash=NULL,status='abandoned' WHERE id=? AND status='active' AND expires_at<=NOW()")->execute([(int)$existing['id']]);}try{$insert=$this->db->prepare("INSERT INTO carts (guest_key_hash,status,expires_at) VALUES (?,'active',DATE_ADD(NOW(),INTERVAL 30 DAY))");$insert->execute([$keyHash]);return (int)$this->db->lastInsertId();}catch(\PDOException){$lookup=$this->db->prepare("SELECT id,(expires_at>NOW()) AS is_current FROM carts WHERE guest_key_hash=? AND status='active' LIMIT 1");$lookup->execute([$keyHash]);$row=$lookup->fetch();return $row&&((int)$row['is_current']===1)?(int)$row['id']:null;} }
    public function touch(int $cartId): void { $this->db->prepare("UPDATE carts SET expires_at=DATE_ADD(NOW(),INTERVAL 30 DAY) WHERE id=? AND status='active'")->execute([$cartId]); }
    public function count(int $cartId): int { $q=$this->db->prepare('SELECT COALESCE(SUM(quantity),0) FROM cart_items WHERE cart_id=?');$q->execute([$cartId]);return (int)$q->fetchColumn(); }
    public function product(int $id): ?array { $q=$this->db->prepare("SELECT id,name,slug,sku,price,sale_price,status,inventory_mode,stock_quantity,is_available,deleted_at FROM products WHERE id=? LIMIT 1");$q->execute([$id]);$r=$q->fetch();return $r?:null; }
    public function variants(int $productId): array { $q=$this->db->prepare('SELECT id,name,option_values,sku,price,price_adjustment,inventory_mode,stock_quantity,is_available,is_active FROM product_variants WHERE product_id=? AND is_active=1 ORDER BY id');$q->execute([$productId]);return $q->fetchAll(); }
    public function variant(int $productId,int $variantId): ?array { $q=$this->db->prepare('SELECT id,product_id,name,option_values,sku,price,price_adjustment,inventory_mode,stock_quantity,is_available,is_active FROM product_variants WHERE id=? AND product_id=? LIMIT 1');$q->execute([$variantId,$productId]);$r=$q->fetch();return $r?:null; }
    public function fields(int $productId): array { $q=$this->db->prepare('SELECT id,product_id,name,field_type,is_required,position,validation_rules,options,additional_price FROM product_customization_fields WHERE product_id=? AND is_active=1 ORDER BY position,id');$q->execute([$productId]);return $q->fetchAll(); }
    public function imageFieldIds(int $productId): array { $q=$this->db->prepare("SELECT id FROM product_customization_fields WHERE product_id=? AND is_active=1 AND field_type='image'");$q->execute([$productId]);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN)); }
    public function itemRows(int $cartId): array
    { $q=$this->db->prepare("SELECT ci.*,p.slug,p.status product_status,p.deleted_at product_deleted_at,p.is_available product_is_available,p.inventory_mode product_inventory_mode,p.stock_quantity product_stock_quantity,p.price product_price,p.sale_price product_sale_price,p.short_description,(SELECT i.file_path FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.position,i.id LIMIT 1) image_path,(SELECT i.alt_text FROM product_images i WHERE i.product_id=p.id ORDER BY i.is_primary DESC,i.position,i.id LIMIT 1) image_alt,v.image_path variant_image_path,v.name variant_name,v.option_values variant_options,v.price variant_price,v.price_adjustment variant_price_adjustment,v.is_active variant_active,v.is_available variant_is_available,v.inventory_mode variant_inventory_mode,v.stock_quantity variant_stock_quantity,EXISTS(SELECT 1 FROM product_variants av WHERE av.product_id=p.id AND av.is_active=1) has_active_variants FROM cart_items ci LEFT JOIN products p ON p.id=ci.product_id LEFT JOIN product_variants v ON v.id=ci.product_variant_id WHERE ci.cart_id=? ORDER BY ci.created_at,ci.id");$q->execute([$cartId]);$rows=$q->fetchAll();if(!$rows)return [];$ids=array_map(static fn(array $r):int=>(int)$r['id'],$rows);$placeholders=implode(',',array_fill(0,count($ids),'?'));$c=$this->db->prepare("SELECT cart_item_id,customization_field_id,field_name_snapshot,field_type,value_text,file_reference,price_adjustment FROM cart_item_customizations WHERE cart_item_id IN ({$placeholders}) ORDER BY id");$c->execute($ids);$custom=[];foreach($c->fetchAll() as $row)$custom[(int)$row['cart_item_id']][]=$row;
        $productIds=array_values(array_unique(array_map(static fn(array $r):int=>(int)$r['product_id'],$rows)));$pp=implode(',',array_fill(0,count($productIds),'?'));$f=$this->db->prepare("SELECT id,product_id,name,field_type,is_required,validation_rules,options,additional_price FROM product_customization_fields WHERE is_active=1 AND product_id IN ({$pp}) ORDER BY position,id");$f->execute($productIds);$fields=[];foreach($f->fetchAll() as $field)$fields[(int)$field['product_id']][]=$field;
        foreach($rows as &$row){$row['customizations']=$custom[(int)$row['id']]??[];$row['fields']=$fields[(int)$row['product_id']]??[];}unset($row);return $rows;
    }
    public function item(int $cartId,string $key): ?array { foreach($this->itemRows($cartId) as $row)if(hash_equals((string)$row['item_key'],$key))return $row;return null; }
    public function sameItem(int $cartId,int $productId,?int $variantId,string $hash,?int $exceptId=null): ?array
    { $sql='SELECT id,item_key,quantity FROM cart_items WHERE cart_id=? AND product_id=? AND customization_hash=? AND '.($variantId===null?'product_variant_id IS NULL':'product_variant_id=?');$args=[$cartId,$productId,$hash];if($variantId!==null)$args[]=$variantId;if($exceptId!==null){$sql.=' AND id<>?';$args[]=$exceptId;}$sql.=' LIMIT 1 FOR UPDATE';$q=$this->db->prepare($sql);$q->execute($args);$r=$q->fetch();return $r?:null; }
    public function insertItem(int $cartId,string $key,int $productId,?int $variantId,string $productName,?string $variantName,string $hash,int $qty,string $unitPrice): int
    { $q=$this->db->prepare('INSERT INTO cart_items (cart_id,item_key,product_id,product_variant_id,product_name_snapshot,variant_name_snapshot,customization_hash,quantity,unit_price) VALUES (?,?,?,?,?,?,?,?,?)');$q->execute([$cartId,$key,$productId,$variantId,$productName,$variantName,$hash,$qty,$unitPrice]);return (int)$this->db->lastInsertId(); }
    public function saveCustomizations(int $itemId,array $rows): void
    { $this->db->prepare('DELETE FROM cart_item_customizations WHERE cart_item_id=?')->execute([$itemId]);$q=$this->db->prepare('INSERT INTO cart_item_customizations (cart_item_id,customization_field_id,field_name_snapshot,field_type,value_text,file_reference,price_adjustment) VALUES (?,?,?,?,?,?,?)');foreach($rows as $row)$q->execute([$itemId,$row['field_id'],$row['label'],$row['type'],$row['value'],$row['file_reference'],$row['price']]); }
    public function attachUpload(int $cartId,int $itemId,int $fieldId,string $reference): void { $this->db->prepare('UPDATE cart_uploads SET cart_item_id=?,customization_field_id=? WHERE cart_id=? AND file_reference=?')->execute([$itemId,$fieldId,$cartId,$reference]); }
    public function updateQuantity(int $itemId,int $qty): void { $this->db->prepare('UPDATE cart_items SET quantity=? WHERE id=?')->execute([$qty,$itemId]); }
    public function updatePrice(int $itemId,string $price): void { $this->db->prepare('UPDATE cart_items SET unit_price=? WHERE id=?')->execute([$price,$itemId]); }
    public function updateVariant(int $itemId,?int $variantId,string $variantName,string $hash,string $price): void { $this->db->prepare('UPDATE cart_items SET product_variant_id=?,variant_name_snapshot=?,customization_hash=?,unit_price=? WHERE id=?')->execute([$variantId,$variantName?:null,$hash,$price,$itemId]); }
    public function deleteItem(int $cartId,int $itemId): void { $this->db->prepare('DELETE FROM cart_items WHERE cart_id=? AND id=?')->execute([$cartId,$itemId]); }
    public function uploadOwned(int $cartId,int $productId,int $fieldId,string $reference,?int $itemId=null): ?array
    { $sql='SELECT file_reference,content_hash,file_size,mime_type,cart_item_id FROM cart_uploads WHERE cart_id=? AND product_id=? AND customization_field_id=? AND file_reference=? AND (cart_item_id IS NULL'.($itemId!==null?' OR cart_item_id=?':'').') LIMIT 1';$args=[$cartId,$productId,$fieldId,$reference];if($itemId!==null)$args[]=$itemId;$q=$this->db->prepare($sql);$q->execute($args);$r=$q->fetch();return $r?:null; }
    public function uploads(int $cartId): array { $q=$this->db->prepare('SELECT file_reference,content_hash,file_size,mime_type,cart_item_id,customization_field_id,product_id FROM cart_uploads WHERE cart_id=?');$q->execute([$cartId]);return $q->fetchAll(); }
    public function removeUnusedUploads(int $cartId): array
    { $q=$this->db->prepare('SELECT u.file_reference FROM cart_uploads u LEFT JOIN cart_item_customizations c ON c.file_reference=u.file_reference WHERE u.cart_id=? AND c.id IS NULL');$q->execute([$cartId]);$refs=$q->fetchAll(PDO::FETCH_COLUMN);if($refs){$p=implode(',',array_fill(0,count($refs),'?'));$d=$this->db->prepare("DELETE FROM cart_uploads WHERE cart_id=? AND file_reference IN ({$p})");$d->execute([$cartId,...$refs]);}return $refs; }
    public function uploadForView(int $cartId,string $reference): ?array { $q=$this->db->prepare('SELECT file_reference,mime_type FROM cart_uploads WHERE cart_id=? AND file_reference=? LIMIT 1');$q->execute([$cartId,$reference]);$r=$q->fetch();return $r?:null; }
}
